S = 'js1-job-pipeline'; P = fe.REG[S]['abs']; os.chdir(P); done = []

fe.append_section(S, '02', '## Why a fake date sorts last', """`GET /api/applications` sorts with `(a.nextStepDate || "9999-99-99").localeCompare(b.nextStepDate || "9999-99-99") || a.id.localeCompare(b.id)` (`server/server.js:35`). Two facts make that correct: `YYYY-MM-DD` is fixed-width and zero-padded, so comparing the strings character by character is the same as comparing the dates; and `"9999-99-99"` is greater than every real date in that comparison, so undated applications sort last. It is a sentinel, not a date: never store it, never parse it, and never copy the trick to a format that is not fixed-width (`3/9/2026` vs `12/1/2026` would sort wrong). The honest alternatives are a comparator that returns `+1` when only `a` is undated, or in SQL `ORDER BY next_step_date NULLS LAST, id`.""")
done.append('review#1 02 explains the sort sentinel and its limits')
